SELECT ROUND(price, 2) AS price, COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0) AS available_stock FROM ${tableName} WHERE product_name = #{productName} AND deleted_at IS NULL
AND code_number = #{codeNumber}
GROUP BY ROUND(price, 2) HAVING COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0) > 0 ORDER BY price DESC

SELECT ROUND(price, 2) AS price, COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0) AS available_stock, COALESCE(SUM(in_quantity), 0) AS total_in, COALESCE(SUM(out_quantity), 0) AS total_out FROM ${tableName} WHERE product_name = #{productName} AND deleted_at IS NULL
AND code_number = #{codeNumber}
GROUP BY ROUND(price, 2) HAVING COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0) > 0 ORDER BY price DESC
